import{c as a,Q as r,j as t,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Skilldex: A Package Manager and Registry for Agent Skill Packages with Hierarchical Scope-Based Distribution","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.16911","title":"Skilldex: A Package Manager and Registry for Agent Skill Packages with Hierarchical Scope-Based Distribution","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.16911,"authors":["Sampriti Saha","Pranav Hemanth"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2604.16911v1","pdf_path":"pdfs/2604.16911.pdf","published_date":"2026-04-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-18-skilldex-package-manager-registry-agent-skills-2604-16911.md","filePath":"research/papers/2026-04-18-skilldex-package-manager-registry-agent-skills-2604-16911.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-04-18-skilldex-package-manager-registry-agent-skills-2604-16911.md"};function l(o,e,n,c,p,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="skilldex-a-package-manager-and-registry-for-agent-skill-packages-with-hierarchical-scope-based-distribution" tabindex="-1">Skilldex: A Package Manager and Registry for Agent Skill Packages with Hierarchical Scope-Based Distribution <a class="header-anchor" href="#skilldex-a-package-manager-and-registry-for-agent-skill-packages-with-hierarchical-scope-based-distribution" aria-label="Permalink to &quot;Skilldex: A Package Manager and Registry for Agent Skill Packages with Hierarchical Scope-Based Distribution&quot;">​</a></h1><p><strong>Authors</strong>: Sampriti Saha, Pranav Hemanth <strong>Published</strong>: April 18, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.16911" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.16911</a> · <a href="https://arxiv.org/html/2604.16911v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.16911 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.16911" target="_blank" rel="noreferrer">research/papers/pdfs/2604.16911.pdf</a> (9 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Model (LLM) agents are increasingly extended at runtime via skill packages, structured natural-language instruction bundles loaded from a well-known directory. Community install tooling and registries exist, but two gaps persist: no public tool scores skill packages against Anthropic&#39;s published format specification, and no mechanism bundles related skills with the shared context they need to remain mutually coherent. We present Skilldex, a package manager and registry for agent skill packages addressing both gaps. The two novel contributions are: (1) compiler-style format conformance scoring against Anthropic&#39;s skill specification, producing line-level diagnostics on description specificity, frontmatter validity, and structural adherence; and (2) the skillset abstraction, a bundled collection of related skills with shared assets (vocabulary files, templates, reference documents) that enforce cross-skill behavioral coherence. Skilldex also provides supporting infrastructure: a three-tier hierarchical scope system, a human-in-the-loop agent suggestion loop, a metadata-only community registry, and a Model Context Protocol (MCP) server. The system is implemented as a TypeScript CLI (skillpm / spm) with a Hono/Supabase registry backend, and is open-source.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>agent skill package 的 package manager + registry，補兩缺口：(a) 無工具對照 Anthropic skill 格式 spec 評分；(b) 無機制把相關 skill 連同共享 context 綁束。兩貢獻：</p><ol><li><strong>Compiler-style format conformance scoring</strong> — 對照 Anthropic skill 規範產 line-level 診斷（description 具體度、frontmatter 有效性、結構符合度）。</li><li><strong>skillset abstraction</strong> — 相關 skill + 共享資產（vocabulary / templates / reference docs）綁束，強制跨 skill 行為一致。</li></ol><p>附：三層 hierarchical scope、human-in-the-loop suggestion loop、metadata-only registry、MCP server。實作為 TypeScript CLI（skillpm/spm）+ Hono/Supabase，開源。</p><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>無量化 benchmark（9 pp，工程/系統論文，1 圖 5 表）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>偏工具/系統貢獻，無效能數字；conformance scoring 的 spec 隨 Anthropic 規範演進需維護。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 skill 審計建議</strong>：compiler-style SKILL.md conformance scoring 可併入 <code>harness-meta</code> 的 schema-verify（本 session schema-lint 已偵測「INDEX no frontmatter」「1 agent schema issue」——正是此類 lint 的需求）。</li><li><strong>skillset abstraction ↔ pilot 群 / review 群</strong>：本 workspace 的 4 pilot（haiku/sonnet/opus/fable）+ review 三件（qp/<code>/pilot frontier</code> 稽核（原 pilot-review）/ship-review）即「相關 skill + 共享紀律」，可作 skillset 綁束的現成案例。</li><li><strong>three-tier scope ↔ auto-load vs on-demand vs path-scoped</strong>：本 workspace 規則已有三態（auto-load / on-demand / path-scoped），與 Skilldex scope 概念同構。</li><li>⚠️ 為外部開源工具（TypeScript/Supabase），非可直接套用；價值在「skill spec lint + skillset 綁束」設計理念，落地走 harness-meta schema-verify 擴充。</li></ul>',18)])])}const k=a(i,[["render",l]]);export{g as __pageData,k as default};
